// Ekstrak No. Pesanan, Username Pembeli, dan Daftar Game (Single & Multi-Item)
const item = $input.item;
const text = item.json.snippet || item.json.textPlain || item.json.html || '';

// 1. Ekstrak Nomor Pesanan
const invoiceMatch = text.match(/#([A-Z0-9]{10,})/i);
const invoice = invoiceMatch ? invoiceMatch[1].trim().toUpperCase() : null;

// 2. Ekstrak Username Pembeli
const buyerMatch = text.match(/pesanan ke\s+([a-zA-Z0-9._]+)/i);
const buyerUsername = buyerMatch ? buyerMatch[1].trim() : 'Pembeli Shopee';

// 3. Ekstrak Tanggal Pesanan
const dateMatch = text.match(/Tanggal Pesanan:\s*([^
]+)/i);
const orderDate = dateMatch ? dateMatch[1].trim() : new Date().toLocaleString('id-ID');

// 4. Ekstrak Setiap Item Game (1., 2., 3., dst.)
const itemRegex = /(\d+)\.\s+([^\n\r]+)(?:[\r\n]+Variasi:\s*([^\n\r]*))?/g;
const items = [];
let match;

while ((match = itemRegex.exec(text)) !== null) {
  const rawTitle = match[2].trim();
  const variation = (match[3] || '').trim();

  // Bersihkan embel-embel judul Shopee
  const cleanTitle = rawTitle
    .replace(/\s*-\s*Game PC.*$/i, '')
    .replace(/\s*-\s*PC Offline.*$/i, '')
    .replace(/\s*-\s*Bisa Auto Update.*$/i, '')
    .trim();

  const isSims4 = /sims 4/i.test(cleanTitle) || /sims 4/i.test(rawTitle);

  items.push({
    index: parseInt(match[1]),
    title: cleanTitle,
    rawTitle: rawTitle,
    variation: variation,
    isSims4: isSims4,
    allowCC: /CC/i.test(variation)
  });
}

if (!invoice || items.length === 0) {
  return [];
}

return [{
  json: {
    invoice,
    buyerUsername,
    orderDate,
    items,
    totalGames: items.length,
    hasSims4: items.some(i => i.isSims4),
    status: 'ready',
    createdAt: new Date().toISOString()
  }
}];
